def detect_scan_modality(filename: str, ocr_text: str = "") -> Dict[str, str]:
    """
    Classifies the uploaded document/image into one of:
    - medication: Pharmaceutical packaging, blister packs, pill bottles
    - prescription: Doctor's prescription slips, Rx orders
    - radiology: X-ray, CT, MRI, Ultrasound, PET scans
    - lab_report: Pathology, blood panels, lab tests
    - general_clinical: General clinical documentation
    """
    combined = f"{filename} {ocr_text}".lower()
    
    # Check for pharmaceutical / medication packaging
    pharma_keywords = [
        "tablet", "tablets", "capsule", "capsules", "mg", "mcg", "ointment", "syrup",
        "suspension", "risperdal", "risperidone", "metformin", "lisinopril", "atorvastatin",
        "warfarin", "amoxicillin", "aspirin", "paracetamol", "ibuprofen", "omeprazole",
        "levothyroxine", "ciprofloxacin", "azithromycin", "doxycycline", "losartan",
        "amlodipine", "semaglutide", "gabapentin", "sertraline", "alprazolam", "clonazepam",
        "hydrochlorothiazide", "prednisone", "furosemide", "pantoprazole", "janssen",
        "pfizer", "novartis", "sanofi", "gsk", "bayer", "roche", "per tablet", "film-coated"
    ]
    if any(k in combined for k in pharma_keywords):
        return {
            "category": "medication",
            "label": "💊 Pharmaceutical / Medication Packaging",
            "modality": "Pharmaceutical Product",
            "badge": "Clinical Pharmacology Engine"
        }
    
    # Check for radiology imaging
    if any(k in combined for k in ["x-ray", "xray", "chest x-ray", "chest xray", "radiograph", "radiology", "ap view", "pa view", "lateral view"]):
        return {
            "category": "radiology",
            "label": "🩻 Radiology Scan (X-Ray)",
            "modality": "X-ray",
            "badge": "Radiology Reasoning Model"
        }
    if any(k in combined for k in ["ct scan", "computed tomography", "ct brain", "ct chest", "ct abdomen", "hounsfield"]):
        return {
            "category": "radiology",
            "label": "🩻 Computed Tomography (CT Scan)",
            "modality": "CT",
            "badge": "Radiology Reasoning Model"
        }
    if any(k in combined for k in ["mri", "magnetic resonance", "t1-weighted", "t2-weighted", "flair", "diffusion"]):
        return {
            "category": "radiology",
            "label": "🩻 Magnetic Resonance Imaging (MRI)",
            "modality": "MRI",
            "badge": "Radiology Reasoning Model"
        }
    if any(k in combined for k in ["ultrasound", "sonography", "echocardiogram", "doppler"]):
        return {
            "category": "radiology",
            "label": "📡 Ultrasound / Sonography",
            "modality": "Ultrasound",
            "badge": "Radiology Reasoning Model"
        }
    
    # Check for laboratory reports
    if any(k in combined for k in ["hemoglobin", "wbc", "rbc", "platelet", "cholesterol", "triglyceride", "hba1c", "creatinine", "blood test", "lab report", "serum", "urinalysis"]):
        return {
            "category": "lab_report",
            "label": "🧪 Laboratory Diagnostic Panel",
            "modality": "Lab Report",
            "badge": "Clinical Pathology Engine"
        }
        
    # Check for prescription slips
    if any(k in combined for k in ["rx", "dr.", "doctor", "clinic", "hospital", "patient name", "prescribed", "sig:", "refills:"]):
        return {
            "category": "prescription",
            "label": "📝 Clinical Prescription Order",
            "modality": "Prescription Slip",
            "badge": "Rx Verification Engine"
        }
        
    return {
        "category": "general_clinical",
        "label": "🩺 Medical Document / Diagnostic Scan",
        "modality": "Clinical Scan",
        "badge": "Clinical Diagnostic AI"
    }


